def polyfit_nmse(u,deg=8):
    A=np.column_stack([u**k for k in range(deg+1)])
    c=np.linalg.lstsq(A,sigma,rcond=None)[0]
    return np.mean((sigma-A@c)**2)/np.var(sigma)
